define(["jquery"],function($){"use strict";var capture=function(config,callback){var status=$(config.status);status.text(config.strings.requesting);if(!navigator.geolocation){status.text(config.strings.error);return}navigator.geolocation.getCurrentPosition(function(position){$(config.latitude).val(position.coords.latitude.toFixed(7));$(config.longitude).val(position.coords.longitude.toFixed(7));if(config.accuracy){$(config.accuracy).val(position.coords.accuracy.toFixed(2))}status.text(config.strings.captured);callback(position)},function(){status.text(config.strings.error)},{enableHighAccuracy:true,timeout:15e3,maximumAge:0})};var initSettings=function(config){$(config.button).on("click",function(){capture(config,function(){})})};var initSubmission=function(config){$(config.button).on("click",function(){capture(config,function(){$(config.submit).prop("disabled",false)})})};var initTeacherCapture=function(config){$(config.button).on("click",function(){capture(config,function(){$(config.status).text(config.strings.captured);$(config.form).trigger("submit")})})};return{initSettings:initSettings,initSubmission:initSubmission,initTeacherCapture:initTeacherCapture}});